/**
 * Power-Bank-Field-Guide.pdf, embedded here as base64 so it ships inside the serverless function bundle without
 * depending on Next.js's static-file tracing (same pattern as asset-handover-poster.ts). Attached to
 * every handover/custody receipt email alongside the receipt PDF and the Asset Handover & Custody
 * Notice.
 *
 * To swap in an updated version: export the new PDF, `base64 -w0 new.pdf` and paste the result in below.
 */
const POWER_BANK_FIELD_GUIDE_BASE64 =
  "";

export function powerBankFieldGuidePdf(): Buffer {
  return Buffer.from(POWER_BANK_FIELD_GUIDE_BASE64, "base64");
}
